def load_conf(fname):
    with open(fname, "r", encoding='utf-8') as f:
        conts = f.read()
    keys=conts.split("\n")
    res={}
    for x in keys:
        try:
            k,v = x.split("=")
            res[k]=v
        except:
            pass
    return res

def save_conf(fname, conf):
    with open(fname, "w", encoding='utf-8') as file:
        for k in conf:
            file.write(f"{k}={conf[k]}\n")
    return
