    return conts

def load_json(fname):
    data_ = get_file_contents(fname)
    data = []
    for line in data_.split("\n"):
        pos = line.find("#")
        if pos >= 0:
            data.append(line[:pos])
        else:
            data.append(line)
    return json.loads("\n".join(data))

def save_json(fname, conf):
