def get_config(val, key, default_val=None):
    if type(key) is list:
        keys_ = key
    else:
        keys_ = key.split("/")
    val_ = val
    for k in keys_:
        val_=val_.get(k)
        if val_ is None: return default_val
    return val_

def set_config(conf, key, val):
    if type(key) is list:
        keys_ = key
    else:
        keys_ = key.split("/")
