#
#
def get_now_str():
    lt=g_rtc.datetime()
    if lt[0] < 2000:
        try:
            ntptime.settime()
        except:
            pass
    return "%s, %02d %s %d %02d:%02d:%02d GMT" % (DAY_A[lt[3]], lt[2], MON_A[lt[1]-1], lt[0], lt[4], lt[5], lt[6])
#
#
def get_now_str2():
    lt=g_rtc.datetime()
    if lt[0] < 2000:
        try:
            ntptime.settime()
        except:
            pass
    return "%s, %02d %s %d %02d:%02d:%02d.%d GMT" % (DAY_A[lt[3]], lt[2], MON_A[lt[1]-1], lt[0], lt[4], lt[5], lt[6], lt[7])

def set_env(pth='/sd/scripts', init=True):
    mount_sd()
    if not pth in sys.path:
        sys.path.append(pth)
    if init:
        init_M5()

def init_M5(rot=3):
    import M5
    from M5 import Widgets
    M5.begin()
    Widgets.setRotation(rot)
    Widgets.fillScreen(0x000000)

def copy_file(frm, to):
    ff = open(frm)
    ft = open(to, 'w')
    ft.write(ff.read())
    ff.close()
    ft.close()

def remove_all_file(dir):
    os.chdir(dir)
    for fname in os.listdir():
        os.remove(fname)

def reset_m5():
    nvs = esp32.NVS("uiflow")
    nvs.set_u8("boot_option", 1)

def check_connection(host, port):
    try:
        sock_ = socket.socket()
        sock_.connect(socket.getaddrinfo(host, port)[0][-1])
        sock_.close()
        return True
    except:
        return False
    
